/// InboxItemKind is what an entry in the needs-you queue is.
enum InboxItemKind {
  inboxItemAgent('agent'),
  inboxItemIntake('intake'),
  inboxItemPull('pull'),
  unknown('unknown');

  const InboxItemKind(this.wire);

  /// The wire text this value stands for.
  final String wire;

  /// The value [wire] names, or [unknown] when this build does not
  /// know it.
  static InboxItemKind fromWire(String wire) {
    for (final value in values) {
      if (value != unknown && value.wire == wire) {
        return value;
      }
    }
    return unknown;
  }
}

/// InboxItem is one entry in the needs-you queue, oldest first.
class InboxItem {
  const InboxItem({
    required this.kind,
    this.agentID,
    this.submission,
    this.pull,
    required this.at,
    this.rawEnums = const {},
  });

  final InboxItemKind kind;
  final String? agentID;
  final PendingSubmission? submission;
  /// Pull carries a "pull" item's ask. It is nil for every other kind.
  final PullAsk? pull;
  final String at;

  /// The wire text of each enum field this build has no value
  /// for, keyed by JSON name, so a round trip keeps it.
  final Map<String, String> rawEnums;

  factory InboxItem.fromJson(Map<String, dynamic> json) {
    final rawEnums = <String, String>{};
    final kindWire = json['kind'] as String;
    final kind = InboxItemKind.fromWire(kindWire);
    if (kind == InboxItemKind.unknown) {
      rawEnums['kind'] = kindWire;
    }
    return InboxItem(
      kind: kind,
      agentID: json['agentId'] as String?,
      submission: _objectOrNull(
        json['submission'],
        PendingSubmission.fromJson,
      ),
      pull: _objectOrNull(
        json['pull'],
        PullAsk.fromJson,
      ),
      at: json['at'] as String,
      rawEnums: rawEnums,
    );
  }

  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    json['kind'] = rawEnums['kind'] ?? kind.wire;
    if (agentID != null) {
      json['agentId'] = agentID;
    }
    if (submission != null) {
      json['submission'] = submission!.toJson();
    }
    if (pull != null) {
      json['pull'] = pull!.toJson();
    }
    json['at'] = at;
    return json;
  }
}

/// InboxDelta is the "inbox" delta on the fleet stream.
class InboxDelta {
  const InboxDelta({
    required this.kind,
    required this.inbox,
