/// PendingSubmission is one submission awaiting an operator's decision, as
/// GET /api/pending lists it.
class PendingSubmission {
  const PendingSubmission({
    this.auto,
    required this.clientID,
    required this.createdAt,
    required this.expiresAt,
    required this.id,
    required this.mode,
    required this.origin,
    this.ownerID,
    required this.plan,
    required this.prompt,
    required this.ref,
    required this.repoID,
    required this.title,
  });

  final bool? auto;
  /// ClientID is the submitting client's id.
  final String clientID;
  /// CreatedAt is when the submission was stored.
  final String createdAt;
  /// ExpiresAt is when it stops being answerable.
  final String expiresAt;
  final String id;
  final String mode;
  final String origin;
  /// OwnerID is never set by today's bridge; unset is the local owner.
  final String? ownerID;
  final String plan;
  final String prompt;
  final String ref;
  final String repoID;
  /// Title is what the operator reads when deciding. It comes from the
  /// calling agent and is therefore untrusted: render as text, never as
  /// markup.
  final String title;

  factory PendingSubmission.fromJson(Map<String, dynamic> json) {
    return PendingSubmission(
      auto: json['auto'] as bool?,
      clientID: json['clientId'] as String,
      createdAt: json['createdAt'] as String,
      expiresAt: json['expiresAt'] as String,
      id: json['id'] as String,
      mode: json['mode'] as String,
      origin: json['origin'] as String,
      ownerID: json['ownerId'] as String?,
      plan: json['plan'] as String,
      prompt: json['prompt'] as String,
      ref: json['ref'] as String,
      repoID: json['repoId'] as String,
      title: json['title'] as String,
    );
  }

  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    json['auto'] = auto;
    json['clientId'] = clientID;
    json['createdAt'] = createdAt;
    json['expiresAt'] = expiresAt;
    json['id'] = id;
    json['mode'] = mode;
    json['origin'] = origin;
    if (ownerID != null) {
      json['ownerId'] = ownerID;
    }
    json['plan'] = plan;
    json['prompt'] = prompt;
    json['ref'] = ref;
    json['repoId'] = repoID;
    json['title'] = title;
    return json;
  }
}

