/// TrustState is a project's trust decision.
enum TrustState {
  trustNA('na'),
  trustUntrusted('untrusted'),
  trustTrusted('trusted'),
  unknown('unknown');

  const TrustState(this.wire);

  /// The wire text this value stands for.
  final String wire;

  /// The value [wire] names, or [unknown] when this build does not
  /// know it.
  static TrustState fromWire(String wire) {
    for (final value in values) {
      if (value != unknown && value.wire == wire) {
        return value;
      }
    }
    return unknown;
  }
}

/// ProjectStatus is one project as GET /api/projects reports it.
class ProjectStatus {
  const ProjectStatus({
    required this.root,
    required this.available,
    this.error,
    required this.trust,
    required this.isolation,
    this.mcpProjectID,
    this.repoID,
    this.orphanWorktrees,
    this.rawEnums = const {},
  });

  final String root;
  final bool available;
  final String? error;
  final TrustState trust;
  /// Isolation is "available", or a human-readable reason isolation cannot
  /// be offered for this project. The composer disables its toggle and shows
  /// the reason, rather than letting a spawn fail.
  final String isolation;
  /// MCPProjectID is the project's stable opaque factory ID: what a client
  /// grant is keyed by, and the only project identifier an MCP client is
  /// given. It is optional so a bridge that has not minted one yet keeps the
  /// response it always had.
  final String? mcpProjectID;
  /// RepoID names the registered repo this project's work comes from: the
  /// repo its settings' intake names, while that repo is still registered.
  /// It is what `GET /api/repos/{id}/issues` is keyed by, so it is what lets
  /// a client ask a project for its issues at all. Omitted for a project
  /// that names none — a local checkout with no remote, which has no issues
  /// to serve — rather than an id the bridge made up.
  final String? repoID;
  /// OrphanWorktrees are worktrees under this project that no known agent
  /// claims. Reported, never deleted — they may hold uncommitted work.
  final List<String>? orphanWorktrees;

  /// The wire text of each enum field this build has no value
  /// for, keyed by JSON name, so a round trip keeps it.
  final Map<String, String> rawEnums;

  factory ProjectStatus.fromJson(Map<String, dynamic> json) {
    final rawEnums = <String, String>{};
    final trustWire = json['trust'] as String;
    final trust = TrustState.fromWire(trustWire);
    if (trust == TrustState.unknown) {
      rawEnums['trust'] = trustWire;
    }
    return ProjectStatus(
      root: json['root'] as String,
      available: json['available'] as bool,
      error: json['error'] as String?,
      trust: trust,
      isolation: json['isolation'] as String,
      mcpProjectID: json['mcpProjectId'] as String?,
      repoID: json['repoId'] as String?,
      orphanWorktrees: _listOrNull(
        json['orphanWorktrees'],
        (value) => value as String,
      ),
      rawEnums: rawEnums,
    );
  }

  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    json['root'] = root;
    json['available'] = available;
    if (error != null) {
      json['error'] = error;
    }
    json['trust'] = rawEnums['trust'] ?? trust.wire;
    json['isolation'] = isolation;
    if (mcpProjectID != null) {
      json['mcpProjectId'] = mcpProjectID;
    }
    if (repoID != null) {
      json['repoId'] = repoID;
    }
    if (orphanWorktrees != null) {
      json['orphanWorktrees'] = orphanWorktrees!;
    }
    return json;
  }
}

