    }
    json['fixRound'] = fixRound;
    json['maxFixRounds'] = maxFixRounds;
    json['tokensUsed'] = tokensUsed;
    json['tokensMax'] = tokensMax;
    json['finished'] = finished;
    json['succeeded'] = succeeded;
    if (baseRef != null) {
