/// OnTrip is what a watch does when it trips. On a row it is what the bridge
/// started it with; on a create request only `reroute` is sent.
class OnTrip {
  const OnTrip({
    this.notify,
    this.resume,
    this.reroute,
  });

  final bool? notify;
  final bool? resume;
  final RerouteRule? reroute;

  factory OnTrip.fromJson(Map<String, dynamic> json) {
    return OnTrip(
      notify: json['notify'] as bool?,
      resume: json['resume'] as bool?,
      reroute: _objectOrNull(
        json['reroute'],
        RerouteRule.fromJson,
      ),
    );
  }

  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    if (notify != null) {
      json['notify'] = notify;
    }
    if (resume != null) {
      json['resume'] = resume;
    }
    if (reroute != null) {
      json['reroute'] = reroute!.toJson();
    }
    return json;
  }
}

/// LastReroute names the reroute a watch's most recent trip made, so a client
/// can undo it (POST /api/reroutes/{id}/undo). The bridge holds reroutes in
/// memory only, so a watch whose trip predates a bridge restart carries none.
class LastReroute {
  const LastReroute({
    required this.id,
    required this.at,
  });

  final String id;
  final int at;

  factory LastReroute.fromJson(Map<String, dynamic> json) {
    return LastReroute(
      id: json['id'] as String,
      at: (json['at'] as num).toInt(),
    );
  }

  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    json['id'] = id;
    json['at'] = at;
    return json;
  }
}

/// WatchInfo is one watch as GET /api/watches answers it: what the engine
/// reports about it, the agent that started it, and what it does on trip
/// (web/bridge/watches.go, internal/acp/watch.go). Times are Unix
/// milliseconds.
class WatchInfo {
  const WatchInfo({
    required this.agentID,
    required this.id,
    required this.name,
    required this.kind,
    required this.state,
    this.condition,
    required this.mode,
    required this.intervalMs,
    this.owner,
    required this.fireCount,
    this.lastSample,
    this.lastError,
    required this.createdAt,
    this.lastFiredAt,
    required this.samples,
    this.onTrip,
    this.notify,
    this.resume,
    this.lastReroute,
  });

  /// AgentID is the agent whose session started the watch, or `studio` for
  /// the bridge's own control session.
  final String agentID;
  final String id;
  final String name;
  final String kind;
  final String state;
  final String? condition;
  final String mode;
  final int intervalMs;
  final String? owner;
  final int fireCount;
  final String? lastSample;
  final String? lastError;
  final int createdAt;
  final int? lastFiredAt;
  final List<WatchSample> samples;
  /// OnTrip, Notify and Resume are held by the bridge, so they appear only
  /// on watches it started. LastReroute is also the bridge's: it is the
  /// record of the watch's last trip that a reroute can still be undone
  /// from, and absent when that trip made no reroute or it was undone.
  final OnTrip? onTrip;
  final bool? notify;
  final bool? resume;
  final LastReroute? lastReroute;

  factory WatchInfo.fromJson(Map<String, dynamic> json) {
    return WatchInfo(
      agentID: json['agentId'] as String,
      id: json['id'] as String,
      name: json['name'] as String,
      kind: json['kind'] as String,
      state: json['state'] as String,
      condition: json['condition'] as String?,
      mode: json['mode'] as String,
      intervalMs: (json['intervalMs'] as num).toInt(),
      owner: json['owner'] as String?,
      fireCount: (json['fireCount'] as num).toInt(),
      lastSample: json['lastSample'] as String?,
      lastError: json['lastError'] as String?,
      createdAt: (json['createdAt'] as num).toInt(),
      lastFiredAt: (json['lastFiredAt'] as num?)?.toInt(),
      samples: _list(
        json['samples'],
        (value) => _object(value, WatchSample.fromJson),
      ),
      onTrip: _objectOrNull(
        json['onTrip'],
        OnTrip.fromJson,
      ),
      notify: json['notify'] as bool?,
      resume: json['resume'] as bool?,
      lastReroute: _objectOrNull(
        json['lastReroute'],
        LastReroute.fromJson,
      ),
    );
  }

  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    json['agentId'] = agentID;
    json['id'] = id;
    json['name'] = name;
    json['kind'] = kind;
    json['state'] = state;
    if (condition != null) {
      json['condition'] = condition;
    }
    json['mode'] = mode;
    json['intervalMs'] = intervalMs;
    if (owner != null) {
      json['owner'] = owner;
    }
    json['fireCount'] = fireCount;
    if (lastSample != null) {
      json['lastSample'] = lastSample;
    }
    if (lastError != null) {
      json['lastError'] = lastError;
    }
    json['createdAt'] = createdAt;
    if (lastFiredAt != null) {
      json['lastFiredAt'] = lastFiredAt;
    }
    json['samples'] = [
      for (final value in samples) value.toJson(),
    ];
    if (onTrip != null) {
      json['onTrip'] = onTrip!.toJson();
    }
    if (notify != null) {
      json['notify'] = notify;
    }
    if (resume != null) {
      json['resume'] = resume;
    }
    if (lastReroute != null) {
      json['lastReroute'] = lastReroute!.toJson();
    }
    return json;
  }
}

/// WatchSpec is what a watch watches: POST /api/watches' `spec`, which the
/// agent's session hands to its watch engine unchanged. Exactly one of
/// Command, JobID and Path carries the source, chosen by Kind.
class WatchSpec {
  const WatchSpec({
    required this.name,
    required this.kind,
    this.command,
    this.jobID,
    this.path,
    this.condition,
    required this.mode,
    required this.intervalMs,
    this.notify,
    this.resume,
  });

  final String name;
  /// command, job or file
  final String kind;
  final String? command;
  final String? jobID;
  final String? path;
  final String? condition;
  /// once or repeat
  final String mode;
  final int intervalMs;
  final bool? notify;
  final bool? resume;

  factory WatchSpec.fromJson(Map<String, dynamic> json) {
    return WatchSpec(
      name: json['name'] as String,
      kind: json['kind'] as String,
      command: json['command'] as String?,
      jobID: json['jobId'] as String?,
      path: json['path'] as String?,
      condition: json['condition'] as String?,
      mode: json['mode'] as String,
      intervalMs: (json['intervalMs'] as num).toInt(),
      notify: json['notify'] as bool?,
      resume: json['resume'] as bool?,
    );
  }

  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    json['name'] = name;
    json['kind'] = kind;
    if (command != null) {
      json['command'] = command;
    }
    if (jobID != null) {
      json['jobId'] = jobID;
    }
    if (path != null) {
      json['path'] = path;
    }
    if (condition != null) {
      json['condition'] = condition;
    }
    json['mode'] = mode;
    json['intervalMs'] = intervalMs;
    if (notify != null) {
      json['notify'] = notify;
    }
    if (resume != null) {
      json['resume'] = resume;
    }
    return json;
  }
}

/// WatchCreate is POST /api/watches' body: the spec, the agent whose session
/// starts it (absent means the bridge's own control session), and the action
/// on trip. A reroute is allowed only on a Studio watch: it rewrites
/// user-global config, which no single agent's watch should be able to do.
class WatchCreate {
  const WatchCreate({
    this.agentID,
    required this.spec,
    this.onTrip,
  });

  final String? agentID;
  final WatchSpec spec;
  final OnTrip? onTrip;

  factory WatchCreate.fromJson(Map<String, dynamic> json) {
    return WatchCreate(
      agentID: json['agentId'] as String?,
      spec: _object(
        json['spec'],
        WatchSpec.fromJson,
      ),
      onTrip: _objectOrNull(
        json['onTrip'],
        OnTrip.fromJson,
      ),
    );
  }

  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    if (agentID != null) {
      json['agentId'] = agentID;
    }
    json['spec'] = spec.toJson();
    if (onTrip != null) {
      json['onTrip'] = onTrip!.toJson();
    }
    return json;
  }
}

